"use strict";

$(document).ready(function () {
  $("body").append(`
        <div id="styleSelector" class="menu-styler">
            <div class="style-toggler">
                <a href="#!"></a>
            </div>

            <div class="style-block">
                <h4 class="mb-2">
                    Ticketo 
                </h4>

                <hr>

                <div class="m-style-scroller">
                    <h6 class="mt-2">Layouts</h6>

                    <div class="theme-color layout-type">
                        <a href="#!" data-value="menu-dark" title="Default Layout">
                            <span></span><span></span>
                        </a>

                        <a href="#!" class="active" data-value="menu-light" title="Light">
                            <span></span><span></span>
                        </a>

                        <a href="#!" data-value="dark" title="Dark">
                            <span></span><span></span>
                        </a>

                        <a href="#!" data-value="reset" title="Reset">
                            Reset
                        </a>
                    </div>
                </div>
            </div>
        </div>
    `);

  setTimeout(function () {
    $(".m-style-scroller").css({
      height: "calc(100vh - 335px)",
      position: "relative",
    });

    new PerfectScrollbar(".m-style-scroller", {
      wheelSpeed: 0.5,
      swipeEasing: false,
      suppressScrollX: true,
      wheelPropagation: true,
      minScrollbarLength: 40,
    });
  }, 400);

  $("#styleSelector > .style-toggler").on("click", function () {
    $("#styleSelector").toggleClass("open");
    $("#styleSelector").removeClass("prebuild-open");
  });

  $(".layout-type > a").on("click", function () {
    var val = $(this).attr("data-value");

    $(".layout-type > a").removeClass("active");
    $(".pcoded-navbar").removeClassPrefix("navbar-image-");
    $(this).addClass("active");

    if (!$(".layout-css").length) {
      $("head").append('<link rel="stylesheet" class="layout-css" href="">');
    }

    if (val === "menu-dark") {
      $(".pcoded-navbar").removeClassPrefix("menu-").removeClass("navbar-dark");
    }

    if (val === "menu-light") {
      $(".pcoded-navbar")
        .removeClassPrefix("menu-")
        .removeClass("navbar-dark")
        .addClass(val);
    }

    if (val === "reset") {
      location.reload();
    }

    if (val === "dark") {
      $(".pcoded-navbar").removeClassPrefix("menu-").addClass("navbar-dark");

      $(".layout-css").attr("href", "assets/css/layout-dark.css");
    } else {
      $(".layout-css").attr("href", "");
    }
  });

  $.fn.removeClassPrefix = function (prefix) {
    this.each(function (_, el) {
      var classes = el.className.split(" ").map(function (cls) {
        return cls.indexOf(prefix) === 0 ? "" : cls;
      });

      el.className = classes.join(" ");
    });

    return this;
  };
});
